    assertEq(sb.__charges.length, 0, '跳过不扣费');
    assert(sb.__toasts.some(t => t.includes('还没在任何板块生效')));
    // 第二道闸(生效板块无沉淀)同样在派生之前
    sb.Store.myProjects = () => [{ id: 'p2', boards: { 分镜: { expert: 'ex_dp' } } }];
